	 * @return ResponseEntity with the created weight record or error status
	 */
	@PostMapping("/owners/{ownerId}/pets/{petId}/weight")
	@ResponseBody
	public ResponseEntity<?> recordWeight(@PathVariable("ownerId") int ownerId, @PathVariable("petId") int petId,
			@Valid @RequestBody WeightRecord weightRecord, BindingResult result) {

		if (result.hasErrors()) {
			return ResponseEntity.badRequest().body("Invalid weight record data");
		}

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);
		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		weightRecord.setPetId(petId);
		WeightRecord saved = this.weightRecords.save(weightRecord);
		return ResponseEntity.status(HttpStatus.CREATED).body(saved);
	}

	/**
	 * REST endpoint to get weight history for a pet.
	 * @param ownerId the ID of the owner
	 * @param petId the ID of the pet
	 * @return ResponseEntity with the list of weight records or error status
	 */
	@GetMapping("/owners/{ownerId}/pets/{petId}/weight/history")
	@ResponseBody
	public ResponseEntity<?> getWeightHistory(@PathVariable("ownerId") int ownerId,
			@PathVariable("petId") int petId) {

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);
		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		List<WeightRecord> history = this.weightRecords.findByPetIdOrderByRecordDateDesc(petId);
		return ResponseEntity.ok(history);
	}

}

